import{_ as l,a0 as o,w as d,s as p,ao as r,I as n,x as s,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 上查找和删除损坏的符号链接 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上查找和删除损坏的符号链接 | LCTT (202006) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上查找和删除损坏的符号链接 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上查找和删除损坏的符号链接 | LCTT (202006) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202006/20200529 How to find and remove broken symlinks on Linux","title":"如何在 Linux 上查找和删除损坏的符号链接","tag":"202006","desc":""},"relativePath":"202006/20200529 How to find and remove broken symlinks on Linux.md","filePath":"[post].md"}'),h={name:"202006/20200529 How to find and remove broken symlinks on Linux.md"};function c(k,e,g,u,b,f){const i=o("Link");return d(),p("div",null,[e[15]||(e[15]=r(`<h1 id="如何在-linux-上查找和删除损坏的符号链接" tabindex="-1">如何在 Linux 上查找和删除损坏的符号链接 <a class="header-anchor" href="#如何在-linux-上查找和删除损坏的符号链接" aria-label="Permalink to “如何在 Linux 上查找和删除损坏的符号链接”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202006/09/095016y7ranx1tssxdsttd.jpg" alt=""></p><blockquote><p>符号链接是指向另一个文件的 Linux 文件。如果删除了被引用的文件，符号链接会保留，但不会显示有问题，除非你尝试使用它。以下是查找和删除指向文件已被删除的符号链接的简单方法。</p></blockquote><p><ruby>符号链接<rt>symbolic link</rt></ruby>在 Linux 系统上扮演了非常有用的角色。它们可以帮助你记住重要文件在系统上的位置，使你更容易访问这些文件，并让你不必为了更方便访问大文件而复制它们，从而节省了大量的空间。</p><h3 id="什么是符号链接" tabindex="-1">什么是符号链接？ <a class="header-anchor" href="#什么是符号链接" aria-label="Permalink to “什么是符号链接？”">​</a></h3><p>通常称它们为“符号链接”或“软链接”，符号链接是非常小的文件。实际上，符号链接真正包含的是它指向的文件的名称，通常包含路径（相对于当前位置或绝对路径）。如果有个名为 <code>ref1</code> 的文件指向名为 <code>/apps/refs/ref-2020</code> 的文件，那么 <code>ref1</code> 的长度将为 19 个字符，即使 <code>ref-202</code> 文件有 2TB。如果指向 <code>./ref-2020</code>，那么长度仅为 10 个字符。如果指向 <code>ref-2020</code>，那么只有 8 个字节。</p><p>如果你执行 <code>vi ref1</code> 之类的命令（其中 <code>ref1</code> 是符号链接的名称），你将编辑 <code>ref1</code> 指向的文件，而不是符号链接本身的内容。Linux 系统知道如何使用符号链接，并且可以做正确的事。同样，如果你使用诸如 <code>cat</code>、<code>more</code>、<code>head</code> 或 <code>tail</code> 之类的命令，那么将查看引用文件的内容。</p><p>另一方面，如果删除符号链接，你将删除该链接，而不是引用的文件。再说一次，Linux 知道怎么做。符号链接使得使用和共享文件更加容易，仅此而已。</p><h4 id="符号链接损坏时" tabindex="-1">符号链接损坏时 <a class="header-anchor" href="#符号链接损坏时" aria-label="Permalink to “符号链接损坏时”">​</a></h4><p>当一个符号链接所指向的文件从系统中删除或重新命名时，符号链接将不再起作用。符号链接只不过是存储在某个特定目录中的引用而已，它不会随着指向它的文件发生变化而更新或删除。它一直指向被引用的文件，即使这个文件早已消失。</p><p>如果你尝试使用指向一个不存在的文件的符号链接，那么将出现如下错误：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ tail whassup</span></span>
<span class="line"><span>tail: cannot open &#39;whassup&#39; for reading: No such file or directory</span></span></code></pre></div><p>如果你尝试访问指向自身的符号链接（是的，奇怪的事情发生了），你将看到类似以下的内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat loopy</span></span>
<span class="line"><span>cat: loopy: Too many levels of symbolic links</span></span>
<span class="line"><span>$ ls -l loopy</span></span>
<span class="line"><span>lrwxrwxrwx 1 shs shs 5 May 28 18:07 loopy -&gt; loopy</span></span></code></pre></div><p>而且，如果（上面的）长列表的第一个字母没有引起你的注意，这表示该文件是符号链接。<code>rwxrwxrwx</code> 权限是标准权限，并不反映符号链接指向的文件的权限。</p><h3 id="查找损坏的符号链接" tabindex="-1">查找损坏的符号链接 <a class="header-anchor" href="#查找损坏的符号链接" aria-label="Permalink to “查找损坏的符号链接”">​</a></h3><p><code>find</code> 命令有一个选项，能让你找到指向不再存在的文件的符号链接。此命令列出当前目录中的符号链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l</span></span></code></pre></div><p><code>l</code> （小写字母 <code>L</code>）告诉 <code>find</code> 命令查找符号链接。</p><p>另一方面，下面的命令在当前目录中查找指向<em>不存在</em>的文件的符号链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l</span></span></code></pre></div><p>为了避免在该命令尝试查找你无权检查的文件或目录时发生错误，你可以将所有错误输出到 <code>/dev/null</code>，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l 2&gt;/dev/null</span></span></code></pre></div><p>你也可以使用此命令找到损坏的符号链接。它比前面的更长，但做的是同样的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l ! -exec test -e {} \\; -print 2&gt;/dev/null</span></span></code></pre></div><h3 id="如何处理损坏的符号链接" tabindex="-1">如何处理损坏的符号链接 <a class="header-anchor" href="#如何处理损坏的符号链接" aria-label="Permalink to “如何处理损坏的符号链接”">​</a></h3><p>除非你知道符号链接引用的文件会被替换，否则最好的方法是直接删除损坏的链接。实际上，如果需要，你可以使用一条命令查找并删除损坏的符号链接，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -xtype l 2&gt;/dev/null -exec rm {} \\;</span></span></code></pre></div><p>该命令的 <code>rm {}</code> 部分会变成“删除文件”的命令</p><p>如果你想将符号链接与不同的文件相关联，你必须先删除该符号链接，然后重新创建它，使其指向新文件。这是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rm ref1</span></span>
<span class="line"><span>$ ln -s /apps/data/newfile ref1</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>符号链接使引用的文件更易于查找和使用，但有时它会比那些宣传去年已经关闭的餐馆的路标还过分。<code>find</code> 命令可以帮助你摆脱损坏的符号链接，或者提醒你没有你可能仍然需要的文件。</p><hr>`,34)),n("p",null,[e[1]||(e[1]=s("via: ",-1)),a(i,{href:"https://www.networkworld.com/article/3546252/how-to-find-and-remove-broken-symlinks-on-linux.html"},{default:t(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3546252/how-to-find-and-remove-broken-symlinks-on-linux.html",-1)])]),_:1})]),n("p",null,[e[6]||(e[6]=s("作者：",-1)),a(i,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:t(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),a(i,{href:"https://github.com/geekpi"},{default:t(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:t(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=s("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:t(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
